#include <iostream>
#include <string>
#include <vector>

enum class Prioridad {
    normal,
    urgente,
    aplazada
};

std::string nombre_prioridad(Prioridad prioridad) {

    if (prioridad == Prioridad::normal) {
        return "Normal";
    }

    if (prioridad == Prioridad::urgente) {
        return "Urgente";
    }

    if (prioridad == Prioridad::aplazada) {
        return "Aplazada";
    }
    return "No reconocida";
}

int main() {
    Prioridad prioridad = Prioridad::urgente;
    std::cout << nombre_prioridad(prioridad);

    return 0;
}

#include <iostream>
#include <string>
#include <vector>

enum class Estado {
    preparado,
    enviado,
    cancelado
};

struct Registro {
    std::string codigo;
    Estado estado;
};

int main() {
    Registro original{"A3", Estado::preparado};
    Registro copia = original;
    original.estado = Estado::enviado;
    std::cout << (copia.estado == Estado::preparado)
              << " " << (original.estado == Estado::preparado);

    return 0;
}

#include <iostream>
#include <string>
#include <vector>

enum class Prioridad {
    normal,
    urgente,
    aplazada
};

struct Registro {
    std::string codigo;
    Prioridad prioridad;
};

std::string nombre_prioridad(Prioridad prioridad) {

    if (prioridad == Prioridad::normal) {
        return "Normal";
    }

    if (prioridad == Prioridad::urgente) {
        return "Urgente";
    }

    if (prioridad == Prioridad::aplazada) {
        return "Aplazada";
    }
    return "No reconocida";
}

int main() {
    std::vector<Registro> registros{
        {"R", Prioridad::urgente},
        {"S", Prioridad::normal}
    };

    for (const auto& registro : registros) {
        std::cout << registro.codigo << ":" << nombre_prioridad(registro.prioridad) << ";";
    }

    return 0;
}

blocks.text:
El ejemplo anterior utiliza dos registros: el código R con Prioridad::urgente y el código S con Prioridad::normal. El recorrido presenta primero el código R, los dos puntos, el texto Urgente y el punto y coma; después hace lo mismo con el segundo registro. El resultado completo es:
R:Urgente;S:Normal;

No hay un salto de línea final. Así recuperamos la asociación entre código y prioridad usando otros datos. La referencia siguiente reúne todos los resultados solicitados en la actividad del editor.

