#include <vector>
#include <iostream>
#include <string>
#include <vector>

enum class Prioridad {
    normal,
    urgente,
    aplazada
};

std::string nombre_prioridad(Prioridad prioridad) {

    if (prioridad == Prioridad::normal) {
        return "Normal";
    }

    if (prioridad == Prioridad::urgente) {
        return "Urgente";
    }

    if (prioridad == Prioridad::aplazada) {
        return "Aplazada";
    }
    return "No reconocida";
}

struct Registro {
    std::string codigo;
    Prioridad prioridad;
};

int main() {
    std::cout << nombre_prioridad(Prioridad::urgente) << "\n";
    std::cout << nombre_prioridad(Prioridad::normal) << "\n";
    std::cout << nombre_prioridad(Prioridad::aplazada) << "\n";
    std::cout << nombre_prioridad(static_cast<Prioridad>(9)) << "\n";

    const std::vector<Registro> registros{
        {"A", Prioridad::normal},
        {"B", Prioridad::urgente},
        {"C", Prioridad::aplazada}
    };

    for (const auto& registro : registros) {
        std::cout << registro.codigo << ":" << nombre_prioridad(registro.prioridad) << ";";
    }

    return 0;
}

